import{renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{feedingTopicFigure}from './eco5-figures.js?v=20261023-physicscomplete01';export function showEco5(spec='conservation',w={}){let[kind,card]=spec.split(':');if(kind==='trophic'&&card==='2')kind='trophic-model';if(kind==='food-security'&&['2','3'].includes(card)){kind='food-security-model';w={scenario:card==='3'?'conflict':'baseline',...w};}if(kind==='conservation'&&card==='2')kind='conservation-model';renderDiagram(w.title||'Follow the evidence',w.label||'Original educational model',feedingTopicFigure({kind,state:card||'0',...w}),'ECOLOGY');}
